/**
 * Jinx Courtier + Vizier: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Courtier
 * Wiki: https://wiki.bloodontheclocktower.com/Vizier
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L115). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import type { ReminderLabel } from '#lib/core/data/index.ts';
import { keepsProtectionTests } from './vizier.test-support.ts';

describe('Courtier + Vizier jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'courtier', 'vizier');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('courtier')?.name).toBe('Courtier');
		expect(data.byId.get('vizier')?.name).toBe('Vizier');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['courtier', 'vizier'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['courtier'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['vizier'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Courtier's Drunk 3 on the Vizier takes their ability, but
	// not their protection by day.
	keepsProtectionTests('courtier', (s) =>
		s.reminder('vizier', 'courtier', 'Drunk 3' as ReminderLabel)
	);
});
